/**
 * Call a method of an object.
 * @param {object} obj - The object.
 * @param {string} name - The method's name.
 * @returns {unknown} What it returned.
 * @example
 * invoke({ f: () => 1 }, "f"); // 1
 */
export function invoke(obj, name) {
	return obj[name]();
}
